import{_ as t,c as s,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易本義通釋卷九","description":"周易本義通釋 - 周易本義通釋卷九","frontmatter":{"title":"周易本義通釋卷九","description":"周易本義通釋 - 周易本義通釋卷九"},"headers":[],"relativePath":"classics/benyi-tongshi/010.md","filePath":"classics/benyi-tongshi/010.md"}'),i={name:"classics/benyi-tongshi/010.md"};function r(o,a,c,p,d,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易本義通釋卷九",tabindex:"-1"},[l("周易本義通釋卷九 "),e("a",{class:"header-anchor",href:"#周易本義通釋卷九","aria-label":"Permalink to “周易本義通釋卷九”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"元胡炳文撰",-1),e("p",null,"有天地，然後萬物生焉。盈天地之間者唯萬物，故受之以屯。屯者，盈也；屯者，理之始生也。物生必蒙，故受之以「蒙」；「蒙」者，蒙也，物之稚也。物稚不可不養也，故受之以「需」；「需」者，飲食之道也。飲食必有訟，故受之以訟。訟必有眾起，故受之以「師」；「師」者，眾也。眾必有所比，故受之以「比」；「比」者，比也。比必有所畜，故受之以「小畜」。物畜然後有禮，故受之以「履」。履而泰，然後安，故受之以「泰」。",-1),e("p",null,"晁氏雲：鄭本無「而泰」二字。",-1),e("p",null,"「泰」者，通也。物不可以終通，故受之以否。物不可以終否，故受之以「同人」。與人同者，物必歸焉，故受之以「大有」。有大者不可以盈，故受之以謙。有大而能謙必豫，故受之以「豫」。豫必有隨，故受之以「隨」。以喜隨人者必有事，故受之以蠱。「蠱」者，事也。有事而後可大，故受之以臨。「臨」者，大也。物大然後可觀，故受之以「觀」。可觀而後有所合，故受之以「噬嗑」。「嗑」者，合也。物不可以苟合而已，故受之以「賁」。「賁」者，飾也。致飾然後亨則盡矣，故受之以「剝」。「剝」者，剝也。物不可以終盡，剝窮上反下，故受之以「復」。復則不妄矣，故受之以「無妄」。有無妄然後可畜，故受之以「大畜」。物畜然後可養，故受之以「頤」。「頤」者，養也。不養則不可動，故受之以「大過」。物不可以終過，故受之以「坎」。「坎」者，陷也。陷必有所麗，故受之以「離」。離者，麗也。右上篇。",-1),e("p",null,"有天地然後有萬物，有萬物然後有男女，有男女然後有夫婦，有夫婦然後有父子，有父子然後有君臣，有君臣然後有上下，有上下然後禮義有所錯。夫婦之道，不可以不久也，故受之以「恆」；恆者，久也。物不可以久居其所，故受之以「遁」；遁者，退也。物不可以終遁，故受之以「大壯」。物不可以終壯，故受之以「晉」；晉者，進也。進必有所傷，故受之以「明夷」；夷者，傷也。傷於外者必反其家，故受之以「家人」。家道窮必乖，故受之以「睽」；睽者，乖也。乖必有難，故受之以「蹇」；蹇者，難也。物不可以終難，故受之以「解」；解者，緩也。緩必有所失，故受之以「損」。損而不已必益，故受之以「益」。益而不已必決，故受之以「夬」；夬者，決也。決必有所遇，故受之以「姤」；姤者，遇也。物相遇而後聚，故受之以「萃」；萃者，聚也。聚而上者謂之升，故受之以「升」。升而不已必困，故受之以「困」。困乎上者必反下，故受之以「井」。井道不可不革，故受之以革。革物者莫若鼎，故受之以鼎。主器者莫若長子，故受之以震。震者，動也。物不可以終動，止之，故受之以艮。艮者，止也。物不可以終止，故受之以漸。漸者，進也。進必有所歸，故受之以歸妹。得其所歸者必大，故受之以豐。豐者，大也。窮大者必失其居，故受之以旅。旅而無所容，故受之以巽。巽者，入也。入而後說之，故受之以兌。兌者，說也。說而後散之，故受之以渙。渙者，離也。物不可以終離，故受之以節。節而信之，故受之以中孚。有其信者必行之，故受之以小過。有過物者必濟，故受之以既濟。物不可窮也，故受之以未濟終焉。右下篇，周易本義通釋卷九，",-1)])])}const f=t(i,[["render",r]]);export{_ as __pageData,f as default};
